WITH c AS (
 SELECT * FROM (
  SELECT * FROM energy_trade_events WHERE booked_ts <= @audit
  LATEST ON booked_ts PARTITION BY trade_id
 ) WHERE trade_ts IN @session AND status != 'CANCELLED'
), flow0 AS (
 SELECT ts,book,curve,qty FROM energy_position_snapshots WHERE ts IN @session
 UNION ALL SELECT trade_ts AS ts,book,curve,qty FROM c
), flow AS (SELECT ts,book,curve,sum(qty) qty FROM flow0 GROUP BY ts,book,curve), running AS (
 SELECT ts,book,curve,sum(qty) OVER (PARTITION BY book,curve ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) pos FROM flow
) SELECT ts,pos,2000000.0 listed_limit FROM running WHERE book='CRUDE' AND curve='BRENT' ORDER BY ts

WITH c AS (
 SELECT * FROM (
  SELECT * FROM energy_trade_events WHERE booked_ts <= @audit
  LATEST ON booked_ts PARTITION BY trade_id
 ) WHERE trade_ts IN @session AND status != 'CANCELLED'
), flow0 AS (
 SELECT ts,book,curve,qty FROM energy_position_snapshots WHERE ts IN @session
 UNION ALL SELECT trade_ts AS ts,book,curve,qty FROM c
), flow AS (SELECT ts,book,curve,sum(qty) qty FROM flow0 GROUP BY ts,book,curve), running AS (
 SELECT ts,book,curve,sum(qty) OVER (PARTITION BY book,curve ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) pos FROM flow
), a AS (SELECT book,curve,min(pos) min_pos,max(pos) max_pos,last(pos) close_pos FROM (SELECT * FROM running ORDER BY ts) GROUP BY book,curve)
SELECT a.*,l.max_abs_qty,l.unit,greatest(abs(min_pos),abs(max_pos))/l.max_abs_qty*100 peak_limit_pct FROM a JOIN energy_limits l ON a.book=l.book AND a.curve=l.curve ORDER BY peak_limit_pct DESC

WITH c AS (
 SELECT * FROM (
  SELECT * FROM energy_trade_events WHERE booked_ts <= @audit
  LATEST ON booked_ts PARTITION BY trade_id
 ) WHERE trade_ts IN @session AND status != 'CANCELLED'
), flow0 AS (
 SELECT ts,book,curve,qty FROM energy_position_snapshots WHERE ts IN @session
 UNION ALL SELECT trade_ts AS ts,book,curve,qty FROM c
), flow AS (SELECT ts,book,curve,sum(qty) qty FROM flow0 GROUP BY ts,book,curve), running AS (
 SELECT ts,book,curve,sum(qty) OVER (PARTITION BY book,curve ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) pos FROM flow
), d AS (SELECT *,lead(ts) OVER (PARTITION BY book,curve ORDER BY ts) next_ts FROM running)
SELECT min(ts) first_breach,max(next_ts) final_exit,sum((next_ts::long-ts::long)/60000000.0) minutes_over_limit,max(pos) peak_bbl FROM d WHERE book='CRUDE' AND curve='BRENT' AND abs(pos)>2000000
